INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','question-tags','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"question-tags","title":"Question tags and agreement in responses","level":"B1","order":52,"summary":"Add a short checking question and match its auxiliary, pronoun and polarity to the statement.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Opposite polarity in a checking tag","Reuse the auxiliary","Keep number and person","Requests and special tags"],"rules":[{"title":"Opposite polarity in a checking tag","explanation":"A usual checking tag is negative after a positive statement and positive after a negative statement. Intonation helps show whether the speaker expects agreement or is genuinely checking. Other tag patterns exist in conversation, but the ordinary opposite-polarity form is a useful starting point.","pattern":"She is ready, **isn’t she**? / She isn’t ready, **is she**?","commonMistakes":["A negative statement can contain never or nobody without the word not. Its checking tag is normally positive."],"examples":["“She prepares the visitor guide every week, **doesn’t she**?”","“She restores the old portrait every week, **doesn’t she**?”"],"skill":"form"},{"title":"Reuse the auxiliary","explanation":"Match the tense and auxiliary of the statement. If it has no auxiliary and is ordinary present or past simple, use do, does or did. Replace a noun subject with an appropriate pronoun.","pattern":"The guide arrived, **didn’t she**?","commonMistakes":["Do not use is as a universal tag auxiliary; it must match the clause."],"examples":["“They did not prepare the visitor guide yesterday, **did they**?”","“They did not restore the old portrait yesterday, **did they**?”"],"skill":"meaning"},{"title":"Keep number and person","explanation":"The tag’s pronoun refers to the statement’s subject, not the nearest noun. Everyone commonly takes they in a tag. There stays there after an existential statement. Standard conversation often uses aren’t I after I am.","pattern":"There is a seat, **isn’t there**? / I’m late, **aren’t I**?","commonMistakes":["Everyone is ready, aren’t they? combines singular agreement in the main clause with singular they in the tag."],"examples":["“We are preparing the visitor guide, **aren’t we**?”","“We are restoring the old portrait, **aren’t we**?”"],"skill":"contrast"},{"title":"Requests and special tags","explanation":"Commands often use will you or would you as a softening tag. Let’s commonly takes shall we. These patterns do not follow the simple positive/negative statement rule. Tags in these exercises are ordinary checking tags unless a special function is named.","pattern":"Let’s leave, **shall we**? / Close the door, **will you**?","commonMistakes":["A comma normally separates a written tag from the statement."],"examples":["“Let’s prepare the visitor guide, **shall we**?”","“Let’s restore the old portrait, **shall we**?”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-tags"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"29ace7aa-2dee-577f-a476-d0accfb1aabd","topicSlug":"question-tags","level":"B1","prompt":"“She prepares the visitor guide every week, ____?”","choices":[{"id":"A","text":"does she"},{"id":"B","text":"isn’t she"},{"id":"C","text":"don’t she"},{"id":"D","text":"doesn’t she"}],"answerId":"D","hint":"Find the tense, subject and positive polarity; then build the **negative matching tag**.","explanation":"The positive present-simple statement with she takes negative **doesn’t she**.","keywords":["positive-present-tag"],"skill":"positive-present-tag","contextKey":"question-tags-1","fingerprint":"c4e791b7451a7b68715fbb694a57625f343a2dfa561b4b9bf0a2a11212506304","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-tags"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the tense, subject and positive polarity; then build the **negative matching tag**.","The positive present-simple statement with she takes negative **doesn’t she**.","Choose **doesn’t she**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This has the same polarity, rather than the ordinary checking tag requested.","B":"The lexical present-simple verb requires does in the tag, not is.","C":"Do does not agree with she.","D":"The positive present-simple statement with she takes negative **doesn’t she**."}}},{"id":"705d2fd5-7df3-544f-abe9-6318bf94e076","topicSlug":"question-tags","level":"B1","prompt":"“They did not prepare the visitor guide yesterday, ____?”","choices":[{"id":"A","text":"didn’t they"},{"id":"B","text":"do they"},{"id":"C","text":"were they"},{"id":"D","text":"did they"}],"answerId":"D","hint":"A negative clause takes a **positive checking tag**.","explanation":"The negative past-simple clause takes the positive tag **did they**.","keywords":["negative-past-tag"],"skill":"negative-past-tag","contextKey":"question-tags-1","fingerprint":"ff3c1a4892fba8e53f8a270c83a167bbcca4a9910924d708876cdc1322eb8f9b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-tags"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A negative clause takes a **positive checking tag**.","The negative past-simple clause takes the positive tag **did they**.","Choose **did they**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The main clause is already negative; the ordinary checking tag is positive.","B":"Do changes the tense to present.","C":"Were does not match the did auxiliary.","D":"The negative past-simple clause takes the positive tag **did they**."}}},{"id":"debc14ec-8237-5ced-af81-3a535336b25b","topicSlug":"question-tags","level":"B1","prompt":"“We are preparing the visitor guide, ____?”","choices":[{"id":"A","text":"isn’t we"},{"id":"B","text":"weren’t we"},{"id":"C","text":"aren’t we"},{"id":"D","text":"don’t we"}],"answerId":"C","hint":"The statement already contains **are**; keep that auxiliary family.","explanation":"Reuse **are** and the pronoun we, with negative polarity.","keywords":["continuous-tag"],"skill":"continuous-tag","contextKey":"question-tags-1","fingerprint":"9350ec66a85b73f2c7f78a58a5903b9320bb23e2d6fdd9c9e0c10b303eba2d97","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-tags"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The statement already contains **are**; keep that auxiliary family.","Reuse **are** and the pronoun we, with negative polarity.","Choose **aren’t we**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Is does not agree with we.","B":"Were changes the time to past.","C":"Reuse **are** and the pronoun we, with negative polarity.","D":"The existing auxiliary is are, not do."}}},{"id":"493fc9be-1a1f-5895-adb2-c77055af8e05","topicSlug":"question-tags","level":"B1","prompt":"“Let’s prepare the visitor guide, ____?”","choices":[{"id":"A","text":"do we"},{"id":"B","text":"aren’t we"},{"id":"C","text":"did we"},{"id":"D","text":"shall we"}],"answerId":"D","hint":"Recognise the special **let’s … shall we?** pattern.","explanation":"The usual tag after a shared suggestion with **let’s** is **shall we**.","keywords":["suggestion-tag"],"skill":"suggestion-tag","contextKey":"question-tags-1","fingerprint":"879a7fc072bc47a2b9d6f503926f0b60e3e6289c80e47bce939d0202d3715115","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-tags"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Recognise the special **let’s … shall we?** pattern.","The usual tag after a shared suggestion with **let’s** is **shall we**.","Choose **shall we**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Do we is not the usual let’s suggestion tag.","B":"The clause has no be construction to match.","C":"A past tag does not fit this present suggestion.","D":"The usual tag after a shared suggestion with **let’s** is **shall we**."}}},{"id":"d998c9ca-f8e5-56b3-a002-1b5a25c4e785","topicSlug":"question-tags","level":"B1","prompt":"“She restores the old portrait every week, ____?”","choices":[{"id":"A","text":"don’t she"},{"id":"B","text":"doesn’t she"},{"id":"C","text":"does she"},{"id":"D","text":"isn’t she"}],"answerId":"B","hint":"Find the tense, subject and positive polarity; then build the **negative matching tag**.","explanation":"The positive present-simple statement with she takes negative **doesn’t she**.","keywords":["positive-present-tag"],"skill":"positive-present-tag","contextKey":"question-tags-2","fingerprint":"7db1580b62d27f8d9935244bdb055285c02a6445407403ceb141ee37a36f24fd","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-tags"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the tense, subject and positive polarity; then build the **negative matching tag**.","The positive present-simple statement with she takes negative **doesn’t she**.","Choose **doesn’t she**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Do does not agree with she.","B":"The positive present-simple statement with she takes negative **doesn’t she**.","C":"This has the same polarity, rather than the ordinary checking tag requested.","D":"The lexical present-simple verb requires does in the tag, not is."}}},{"id":"08ed3ae2-6a0c-5f61-aa69-5185b9d2697b","topicSlug":"question-tags","level":"B1","prompt":"“They did not restore the old portrait yesterday, ____?”","choices":[{"id":"A","text":"did they"},{"id":"B","text":"didn’t they"},{"id":"C","text":"do they"},{"id":"D","text":"were they"}],"answerId":"A","hint":"A negative clause takes a **positive checking tag**.","explanation":"The negative past-simple clause takes the positive tag **did they**.","keywords":["negative-past-tag"],"skill":"negative-past-tag","contextKey":"question-tags-2","fingerprint":"25af95846aa9e20f6eaeb39068015515a9535b240fe971500efd4d28ce4b89e0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-tags"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A negative clause takes a **positive checking tag**.","The negative past-simple clause takes the positive tag **did they**.","Choose **did they**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The negative past-simple clause takes the positive tag **did they**.","B":"The main clause is already negative; the ordinary checking tag is positive.","C":"Do changes the tense to present.","D":"Were does not match the did auxiliary."}}},{"id":"504105ed-9882-5105-a3c5-0289edc7b192","topicSlug":"question-tags","level":"B1","prompt":"“We are restoring the old portrait, ____?”","choices":[{"id":"A","text":"don’t we"},{"id":"B","text":"isn’t we"},{"id":"C","text":"weren’t we"},{"id":"D","text":"aren’t we"}],"answerId":"D","hint":"The statement already contains **are**; keep that auxiliary family.","explanation":"Reuse **are** and the pronoun we, with negative polarity.","keywords":["continuous-tag"],"skill":"continuous-tag","contextKey":"question-tags-2","fingerprint":"eb31a0c5b662b615f38618121cf9ae3ee454470f704500acb101e2eb160dffb0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-tags"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The statement already contains **are**; keep that auxiliary family.","Reuse **are** and the pronoun we, with negative polarity.","Choose **aren’t we**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The existing auxiliary is are, not do.","B":"Is does not agree with we.","C":"Were changes the time to past.","D":"Reuse **are** and the pronoun we, with negative polarity."}}},{"id":"51537031-971a-5c8e-a8ed-70db802b9b9f","topicSlug":"question-tags","level":"B1","prompt":"“Let’s restore the old portrait, ____?”","choices":[{"id":"A","text":"aren’t we"},{"id":"B","text":"did we"},{"id":"C","text":"shall we"},{"id":"D","text":"do we"}],"answerId":"C","hint":"Recognise the special **let’s … shall we?** pattern.","explanation":"The usual tag after a shared suggestion with **let’s** is **shall we**.","keywords":["suggestion-tag"],"skill":"suggestion-tag","contextKey":"question-tags-2","fingerprint":"083a917fb90eb72013bae930af4531b10eb78f4c74ad1a379c791c5e940bad63","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-tags"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Recognise the special **let’s … shall we?** pattern.","The usual tag after a shared suggestion with **let’s** is **shall we**.","Choose **shall we**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The clause has no be construction to match.","B":"A past tag does not fit this present suggestion.","C":"The usual tag after a shared suggestion with **let’s** is **shall we**.","D":"Do we is not the usual le